parameters.command:
cat > check_password.sh << 'EOFSCRIPT'
#!/bin/bash

USERNAME=$1
PASSWORD=$2

# Verify the user exists
if ! id "$USERNAME" &>/dev/null; then
    echo "User does not exist"
    exit 1
fi

# Check if expect is installed
if ! command -v expect &>/dev/null; then
    echo "expect is not installed"
    exit 1
fi

# Test SSH password using expect
expect << EOF
set timeout 10
spawn ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null $USERNAME@localhost
expect {
    "password:" {
        send "$PASSWORD\r"
        expect {
            "$ " { exit 0 }
            "# " { exit 0 }
            timeout { exit 1 }
            eof { exit 1 }
        }
    }
    timeout { exit 1 }
    eof { exit 1 }
}
EOF

exit $?
EOFSCRIPT
